package com.smarthome.command;

import java.time.Instant;
import java.util.UUID;

import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** One remote command. State changes are made with conditional bulk updates (see DeviceCommandRepository). */
@Entity
@Table(name = "device_commands")
public class DeviceCommand {

	/** Generated by the backend (random UUID) and used as the command ID on the wire. */
	@Id
	private UUID id;

	@Column(name = "device_uuid", nullable = false)
	private UUID deviceUuid;

	@Column(name = "requested_by", nullable = false)
	private UUID requestedBy;

	@Column(nullable = false, length = 30)
	private String action;

	@Column(name = "action_value", nullable = false, length = 10)
	private String value;

	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	@Column(nullable = false, length = 20)
	private CommandStatus status;

	@Column(name = "created_at", nullable = false)
	private Instant createdAt;

	@Column(name = "expires_at", nullable = false)
	private Instant expiresAt;

	@Column(name = "sent_at")
	private Instant sentAt;

	@Column(name = "completed_at")
	private Instant completedAt;

	@Column(length = 120)
	private String detail;

	/** Who/what asked for it besides a person clicking: for example "automation:Night light". Null for manual commands. */
	@Column(length = 80)
	private String origin;

	protected DeviceCommand() {
	}

	public DeviceCommand(UUID id, UUID deviceUuid, UUID requestedBy, String action, String value, Instant now, Instant expiresAt,
			String origin) {
		this.origin = origin;
		this.id = id;
		this.deviceUuid = deviceUuid;
		this.requestedBy = requestedBy;
		this.action = action;
		this.value = value;
		this.status = CommandStatus.PENDING;
		this.createdAt = now;
		this.expiresAt = expiresAt;
	}

	public UUID getId() { return id; }
	public UUID getDeviceUuid() { return deviceUuid; }
	public UUID getRequestedBy() { return requestedBy; }
	public String getAction() { return action; }
	public String getValue() { return value; }
	public CommandStatus getStatus() { return status; }
	public Instant getCreatedAt() { return createdAt; }
	public Instant getExpiresAt() { return expiresAt; }
	public Instant getSentAt() { return sentAt; }
	public Instant getCompletedAt() { return completedAt; }
	public String getDetail() { return detail; }
	public String getOrigin() { return origin; }
}
